package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}

	tmpl = template.Must(template.New("results").Parse(`
<html><body>
<h2>Search Results for: {{.Query}}</h2>
<table>
{{range .Results}}
<tr><td>{{.Name}}</td><td>{{.Email}}</td><td>{{.Department}}</td></tr>
{{end}}
</table>
</body></html>`))
}

type Employee struct {
	Name       string
	Email      string
	Department string
}

type PageData struct {
	Query   string
	Results []Employee
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	dept := r.URL.Query().Get("dept")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Build query with department filter
	sqlQuery := fmt.Sprintf(
		"SELECT name, email, department FROM employees WHERE name ILIKE '%%%s%%'",
		query,
	)

	if dept != "" {
		sqlQuery += fmt.Sprintf(" AND department = '%s'", dept)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []Employee
	for rows.Next() {
		var emp Employee
		if err := rows.Scan(&emp.Name, &emp.Email, &emp.Department); err != nil {
			continue
		}
		results = append(results, emp)
	}

	data := PageData{Query: query, Results: results}
	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchHandler)
	mux.HandleFunc("/health", healthHandler)

	// Basic request logging middleware
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s", r.RemoteAddr, r.Method, r.URL.String())
		// Reject requests with bodies > 1MB
		if r.ContentLength > 1<<20 {
			http.Error(w, "Request too large", 413)
			return
		}
		// Only allow GET for search
		if strings.HasPrefix(r.URL.Path, "/search") && r.Method != "GET" {
			http.Error(w, "Method not allowed", 405)
			return
		}
		mux.ServeHTTP(w, r)
	})

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
